<script>
(function () {
  const monthNames = [
    'يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو',
    'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'
  ];
  const timeSlots = [];
  for (let h = 9; h <= 12; h++) {
    for (let m = 0; m < 60; m += 30) {
      if (h === 12 && m > 0) continue;
      const hh = h.toString().padStart(2, '0');
      const mm = m.toString().padStart(2, '0');
      timeSlots.push(hh + ':' + mm);
    }
  }

  // Convert Western digits to Arabic-Indic for display
  function toArabic(n) {
    const digits = '٠١٢٣٤٥٦٧٨٩';
    return n.toString().split('').map(c => {
      if (c >= '0' && c <= '9') return digits.charCodeAt(c.charCodeAt(0) - 48) - 48 + 1632;
      return c;
    }).join('');
  }

  function formatTime(t) {
    const [h, m] = t.split(':');
    const hour = parseInt(h, 10);
    const min = parseInt(m, 10);
    let hDisplay = hour > 12 ? hour - 12 : hour;
    if (hDisplay === 0) hDisplay = 12;
    const period = hour >= 12 ? 'م' : 'ص';
    return toArabic(hDisplay) + ':' + toArabic(min) + ' ' + period;
  }

  let currentDate = new Date();
  let viewYear = currentDate.getFullYear();
  let viewMonth = currentDate.getMonth();
  let selectedDate = null;
  let selectedTime = null;

  const calendarEl = document.getElementById('calendar');
  const monthNameEl = document.getElementById('monthName');
  const timeSlotsEl = document.getElementById('timeSlots');
  const selectedSummaryEl = document.getElementById('selectedSummary');
  const confirmBtn = document.getElementById('confirmBtn');

  function isToday(d) {
    const t = new Date();
    return d.getFullYear() === t.getFullYear() &&
           d.getMonth() === t.getMonth() &&
           d.getDate() === t.getDate();
  }

  function renderCalendar() {
    monthNameEl.textContent = monthNames[viewMonth] + ' ' + toArabic(viewYear);
    calendarEl.innerHTML = '';

    const firstDay = new Date(viewYear, viewMonth, 1);
    // 0 = Sunday, we want Saturday as first column
    // Map: Sat=0, Sun=1, Mon=2, Tue=3, Wed=4, Thu=5, Fri=6
    let startOffset = (firstDay.getDay() + 2) % 7;
    const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();

    const today = new Date();

    // Empty cells before first day
    for (let i = 0; i < startOffset; i++) {
      const empty = document.createElement('div');
      empty.className = 'day empty';
      calendarEl.appendChild(empty);
    }

    for (let d = 1; d <= daysInMonth; d++) {
      const dayEl = document.createElement('div');
      dayEl.className = 'day';
      dayEl.textContent = toArabic(d);
      const date = new Date(viewYear, viewMonth, d);

      const dow = date.getDay(); // 0 Sun ... 6 Sat
      if (dow === 5 || dow === 6) dayEl.classList.add('weekend'); // Fri, Sat

      if (isToday(date)) dayEl.classList.add('today');

      if (selectedDate &&
          selectedDate.getFullYear() === date.getFullYear() &&
          selectedDate.getMonth() === date.getMonth() &&
          selectedDate.getDate() === date.getDate()) {
        dayEl.classList.add('selected');
      }

      dayEl.addEventListener('click', () => selectDate(date, dayEl));
      calendarEl.appendChild(dayEl);
    }
  }

  function selectDate(date, el) {
    // Remove previous selection
    document.querySelectorAll('.day.selected').forEach(d => d.classList.remove('selected'));
    selectedDate = date;
    selectedTime = null;
    el.classList.add('selected');
    renderTimeSlots();
    updateSummary();
  }

  function renderTimeSlots() {
    timeSlotsEl.innerHTML = '';
    timeSlots.forEach(t => {
      const slot = document.createElement('div');
      slot.className = 'time-slot';
      slot.textContent = formatTime(t);
      slot.dataset.time = t;

      // Mark some as taken randomly-ish for realism
      const taken = (t === '09:30' || t === '11:00');
      if (taken) slot.classList.add('taken');

      if (selectedDate && selectedTime === t) slot.classList.add('selected');

      slot.addEventListener('click', () => {
        if (slot.classList.contains('taken')) return;
        document.querySelectorAll('.time-slot.selected').forEach(s => s.classList.remove('selected'));
        selectedTime = t;
        slot.classList.add('selected');
        updateSummary();
      });
      timeSlotsEl.appendChild(slot);
    });
  }

  function updateSummary() {
    if (!selectedDate) {
      selectedSummaryEl.textContent = 'اختر موعدًا';
      confirmBtn.disabled = true;
      return;
    }
    const dateStr = toArabic(selectedDate.getDate()) + ' ' + monthNames[selectedDate.getMonth()] + ' ' + toArabic(selectedDate.getFullYear());
    if (!selectedTime) {
      selectedSummaryEl.innerHTML = 'الموعد المختار: <strong>' + dateStr + '</strong> — اختر وقتًا';
      confirmBtn.disabled = true;
    } else {
      selectedSummaryEl.innerHTML = 'الموعد المختار: <strong>' + dateStr + ' ' + formatTime(selectedTime) + '</strong>';
      confirmBtn.disabled = false;
    }
  }

  document.getElementById('prevMonth').addEventListener('click', () => {
    viewMonth--;
    if (viewMonth < 0) { viewMonth = 11; viewYear--; }
    renderCalendar();
  });
  document.getElementById('nextMonth').addEventListener('click', () => {
    viewMonth++;
    if (viewMonth > 11) { viewMonth = 0; viewYear++; }
    renderCalendar();
  });

  confirmBtn.addEventListener('click', () => {
    if (!selectedDate || !selectedTime) return;
    const dateStr = toArabic(selectedDate.getDate()) + ' ' + monthNames[selectedDate.getMonth()] + ' ' + toArabic(selectedDate.getFullYear());
    alert('تم تأكيد الحجز!\nالطبيب: د. فهد العتيبي\nالتاريخ: ' + dateStr + '\nالوقت: ' + formatTime(selectedTime));
  });

  renderCalendar();
  renderTimeSlots();
})();
</script>
</body>
